const withAudit = (action, fn, sink) => async function (...args) {
  const actor = currentSubject();
  sink.record({ actor, action, outcome: 'attempt' });
  try {
    const result = await fn.apply(this, args);
    sink.record({ actor, action, outcome: 'ok' });
    return result;
  } catch (err) {
    sink.record({ actor, action, outcome: 'failed' });
    throw err;
  }
};

