const audited = (target, sink, actor) => new Proxy(target, {
  get(obj, prop, recv) {
    const value = Reflect.get(obj, prop, recv);
    if (typeof value !== 'function') return value;
    return function (...args) {
      sink.record({ actor, action: String(prop), outcome: 'attempt' });
      try {
        const r = value.apply(obj, args);
        if (r && typeof r.then === 'function') {
          return r.then(
            result => { sink.record({ actor, action: String(prop), outcome: 'ok' }); return result; },
            err => { sink.record({ actor, action: String(prop), outcome: 'failed' }); throw err; },
          );
        }
        sink.record({ actor, action: String(prop), outcome: 'ok' });
        return r;
      } catch (e) {
        sink.record({ actor, action: String(prop), outcome: 'failed' });
        throw e;
      }
    };
  },
});
